BEGIN
  exclusive intake barrier: wait for earlier admission commits;
  auction FOR NO KEY UPDATE; acquire lease and check epoch;
  first QUEUED prefix ORDER BY intake_seq FOR UPDATE (<=512);
  release intake barrier; evaluate the prefix in order;
  write decisions + offers + states + separate hash events;
  advance version/watermark; insert latest-version outbox row;
COMMIT; broker ACK follows resolution.
